</code></pre> <pre><code>function reverse(x: number): number {
    const INT_MIN = -(2 ** 31);
    const INT_MAX = 2 ** 31 - 1;
    let rev = 0;
    const sign = x &lt; 0 ? -1 : 1;
    x = Math.abs(x);

    while (x !== 0) {
        const digit = x % 10;
        x = Math.floor(x / 10);
        if (rev &gt; Math.floor((INT_MAX - digit) / 10)) return 0;
        rev = rev * 10 + digit;
    }

    return sign * rev;
}
