                    j += 1
            while i &lt;= mid:
                temp.append(nums[i])
                i += 1
            while j &lt;= right:
                temp.append(nums[j])
                j += 1
            nums[left:right + 1] = temp

        merge_sort(0, len(nums) - 1)
        return nums
</code></pre> <pre><code>#include &lt;vector&gt;

class Solution {
public:
